#include <bits/stdc++.h>
#include <iostream>
#include<vector> 
#include<algorithm>
using namespace std;

 void solve(){
     int n;
     cin>>n;
     vector<long long>a(3*n);
     for(int i=0;i<3*n;++i){
         cin>>a[i];
    }
 sort(a.rbegin(),a.rend());
 vector< long long>pref(3*n+1,0);
 for(int i=0;i<3*n;++i){
     pref[i+1]=pref[i]+a[i];
     
 }
  auto get_val=[&](int k1,int k2)->long long{
      return 2*pref[k1]+pref[k1+2*k2]+3*pref[3*n-2*k1-k2];
  }
 ;
 long long max_strenght=0;
 for(int k1=0;k1<=n;++k1){
     int low=0,high=n-k1;
     while(low<high){
         int mid = low+(high-low)/2;
         long long diff=a[k1+2*mid]+a[k1+2*mid+1]-3*a[3*n-2*k1-mid-1];
         if(diff>0){
             low=mid+1;
             
         }else{
             high=mid;
         }
     }
     for(int k2=max(0,low-1);
     k2<=min(n-k1,low+1);++k2){
         max_strenght=max(max_strenght,get_val(k1,k2));
         
     }
 }
  cout<<max_strenght<<"\n";
 }
 
int main() {
  ios::sync_with_stdio(false);
  cin.tie(nullptr);
  int t;
 if(cin>>t){
      while(t--){
          solve();
      }
  }
 return 0;
}
